// Generate `std-charter.gen.ts` — the core catalogue as a module the browser
// bundle can import.
//
//   deno run -A tento/tento-ui-js/scripts/gen-charter.deno.ts
//
// The allowlist is a text file and the page needs it at runtime, so this joins
// `std-charter.allowlist` (tag, category) to every storybook class that
// declares `tags()` and writes the result as TypeScript. The module imports
// each core example DIRECTLY, which is what lets core stories leave the
// catalogue's hand-written `examples.ts`: adding a core story is "write the
// example with `tags()`, add the allowlist line, regenerate".
//
// The output is committed. esbuild has no pre-build hook and the review
// harness builds from committed source, so a generated-at-build file would be
// a second copy nobody could review. `check-charter` rule 7 fails when the
// committed file differs from what this would write, byte for byte.
//
// Factories, not instances: today every story is constructed at module load
// and the "All" tab renders the union. `make` keeps construction lazy per bind.
import { admissions, ALLOWLIST, categoryOf, ROOT, stories, UI } from "./charter-lib.deno.ts";

export const OUTPUT = `${UI}/std-charter.gen.ts`;

export async function generate(): Promise<string> {
  const rows = admissions(await Deno.readTextFile(ALLOWLIST));
  const category = categoryOf(rows);
  const { stories: cards } = await stories();
  const core = cards.filter((c) => c.tags.every((t) => category.has(t)));

  // One import per example file; a file with two classes imports both names.
  const byExample = new Map<string, string[]>();
  for (const c of core) {
    const names = byExample.get(c.example) ?? [];
    names.push(c.className);
    byExample.set(c.example, names);
  }
  for (const example of byExample.keys()) {
    try {
      await Deno.stat(`${ROOT}${example}`);
    } catch {
      throw new Error(`gen-charter: ${example} does not exist — a stale story would 404 every route`);
    }
  }

  const lines: string[] = [];
  lines.push("// GENERATED by scripts/gen-charter.deno.ts from std-charter.allowlist and");
  lines.push("// every storybook that declares tags(). Do not edit; regenerate with:");
  lines.push("//   deno run -A tento/tento-ui-js/scripts/gen-charter.deno.ts");
  lines.push("// check-charter rule 7 fails when this file is stale.");
  lines.push('import type { Storybook } from "./ui/storybook";');
  lines.push('import type { StdCharter } from "./std-charter";');
  for (const [example, names] of [...byExample].sort()) {
    const spec = "./" + example.slice("tento-ui-js/".length).replace(/\.ts$/, "");
    lines.push(`import { ${names.sort().join(", ")} } from "${spec}";`);
  }
  lines.push("");
  lines.push("export namespace StdCharterGen {");
  lines.push("  export type Tag = { tag: string; category: StdCharter.Category };");
  lines.push("  export type Story = {");
  lines.push("    make: () => Storybook;");
  lines.push("    /** Primary first — the card is placed by tags[0]. */");
  lines.push("    tags: string[];");
  lines.push("    /** Repo-relative, the form `<std-storybook-card example=…>` takes. */");
  lines.push("    example: string;");
  lines.push("    className: string;");
  lines.push("  };");
  lines.push("");
  lines.push("  /** Every std- line of the allowlist, in file order. */");
  lines.push("  export const TAGS: readonly Tag[] = [");
  for (const r of rows) {
    if (!r.tag.startsWith("std-")) continue;
    lines.push(`    { tag: "${r.tag}", category: "${r.category}" },`);
  }
  lines.push("  ];");
  lines.push("");
  lines.push("  /** Every core story, in example-path order. */");
  lines.push("  export const STORIES: readonly Story[] = [");
  for (const c of core) {
    const tags = c.tags.map((t) => `"${t}"`).join(", ");
    lines.push(`    {`);
    lines.push(`      make: () => new ${c.className}(),`);
    lines.push(`      tags: [${tags}],`);
    lines.push(`      example: "${c.example}",`);
    lines.push(`      className: "${c.className}",`);
    lines.push(`    },`);
  }
  lines.push("  ];");
  lines.push("}");
  return lines.join("\n") + "\n";
}

if (import.meta.main) {
  const text = await generate();
  await Deno.writeTextFile(OUTPUT, text);
  const n = (text.match(/^    \{$/gm) ?? []).length;
  console.log(`gen-charter: wrote ${OUTPUT.slice(ROOT.length)} — ${n} stories`);
}
